export const STATUS_ICON_SVG: Record<string, string> = Object.fromEntries(
  Object.entries(STATUS_ICON_SVG_SOURCE).map(([id, markup]) => [
    id,
    markup.includes('xmlns="http://www.w3.org/2000/svg"')
      ? markup
      : markup.replace("<svg ", '<svg xmlns="http://www.w3.org/2000/svg" '),
  ]),
);

export function statusIconMarkup(id: string): string {
  return STATUS_ICON_SVG[id] ?? STATUS_ICON_SVG.folder ?? "";
}
